import openpyxl, os
wb = openpyxl.load_workbook(os.environ['IN_XLSX'], data_only=False)
ws = wb.active
from openpyxl.utils import column_index_from_string
for col in ['AC','CH','CC']:
    ci = column_index_from_string(col)
    print('=== col', col, '===')
    for r in range(2, 5):
        v = ws.cell(row=r, column=ci).value
        if hasattr(v, 'text'):
            print(r, 'ARRAY', repr(v.text), 'ref', v.ref)
        else:
            print(r, repr(v))
